ofiles.wordpress.org/up1512001/\">up1512001</a> · <a href=\"https://profiles.wordpress.org/upadalavipul/\">upadalavipul</a> · <a href=\"https://profiles.wordpress.org/utsavladani/\">Utsav Ladani</a> · <a href=\"https://profiles.wordpress.org/rajanarahul93/\">Vara Rahul Rajana</a> · <a href=\"https://profiles.wordpress.org/sheldorofazeroth/\">Vedansh Mishra</a> · <a href=\"https://profiles.wordpress.org/vedantere/\">Vedant Ere</a> · <a href=\"https://profiles.wordpress.org/vedantgandhi28/\">Vedant Gandhi</a> · <a href=\"https://profiles.wordpress.org/supernovia/\">Velda</a> · <a href=\"https://profiles.wordpress.org/vgnavada/\">vgnavada</a> · <a href=\"https://profiles.wordpress.org/vcanales/\">Vicente Canales</a> · <a href=\"https://profiles.wordpress.org/szepeviktor/\">Viktor Szépe</a> · <a href=\"https://profiles.wordpress.org/vincentbdrt/\">Vincent Bodart</a> · <a href=\"https://profiles.wordpress.org/vineet2003/\">Vinit</a> · <a href=\"https://profiles.wordpress.org/vishitshah/\">Vishit Shah</a> · <a href=\"https://profiles.wordpress.org/vishnuprajapat/\">vishnu prajapat</a> · <a href=\"https://profiles.wordpress.org/vivekawsm/\">vivekawsm</a> · <a href=\"https://profiles.wordpress.org/vortfu/\">vortfu</a> · <a href=\"https://profiles.wordpress.org/vrajadas/\">Vraja Das</a> · <a href=\"https://profiles.wordpress.org/vrishabhsk/\">Vrishabh Jasani</a> · <a href=\"https://profiles.wordpress.org/w3bdsgn/\">w3bdsgn</a> · <a href=\"https://profiles.wordpress.org/webmandesign/\">WebMan Design | Oliver Juhas</a> · <a href=\"https://profiles.wordpress.org/webverts/\">webVerts</a> · <a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a> · <a href=\"https://profiles.wordpress.org/whaze/\">whaze</a> · <a href=\"https://profiles.wordpress.org/skorasaurus/\">Will Skora</a> · <a href=\"https://profiles.wordpress.org/williampatton/\">williampatton</a> · <a href=\"https://profiles.wordpress.org/wolf45/\">wolf45</a> · <a href=\"https://profiles.wordpress.org/wongjn/\">wongjn</a> · <a href=\"https://profiles.wordpress.org/iqbal1hossain/\">WP Shark</a> · <a href=\"https://profiles.wordpress.org/wpexplorer/\">WPExplorer</a> · <a href=\"https://profiles.wordpress.org/wpsoul/\">wpsoul</a> · <a href=\"https://profiles.wordpress.org/xate/\">xate</a> · <a href=\"https://profiles.wordpress.org/xibe/\">Xavier Borderie</a> · <a href=\"https://profiles.wordpress.org/xavilc/\">xavilc</a> · <a href=\"https://profiles.wordpress.org/xerpa43/\">xerpa43</a> · <a href=\"https://profiles.wordpress.org/tikifez/\">Xristopher Anderton</a> · <a href=\"https://profiles.wordpress.org/yankiara/\">Yan</a> · <a href=\"https://profiles.wordpress.org/yashjawale/\">Yash Jawale</a> · <a href=\"https://profiles.wordpress.org/yogeshbhutkar/\">Yogesh Bhutkar</a> · <a href=\"https://profiles.wordpress.org/fierevere/\">Yui</a> · <a href=\"https://profiles.wordpress.org/yuliyan/\">Yuliyan Slavchev</a> · <a href=\"https://profiles.wordpress.org/yusufmudagal/\">Yusuf Mudagal</a> · <a href=\"https://profiles.wordpress.org/zebulan/\">Zebulan Stanphill</a> · <a href=\"https://profiles.wordpress.org/znuff/\">Znuff</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Über <a href=\"https://translate.wordpress.org/stats/\">20 Lokalisierungsteams haben WordPress 7.1 vollständig in ihre Sprache übersetzt</a>, was diese Version zu einer der Versionen mit den meisten vollständigen Übersetzungen am Veröffentlichungstag macht. Die Übersetzungsteams arbeiten mit Hochdruck daran, dass weitere Übersetzungen folgen. Vielen Dank an alle, die dazu beitragen, WordPress in über 200 Sprachen verfügbar zu machen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Nicht zuletzt gilt unser Dank den Freiwilligen, die in den <a href=\"https://de.wordpress.org/support/\">Support-Foren</a> mitwirken und Fragen von WordPress-Anwendern aus aller Welt beantworten.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Mach mit</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Die Mitwirkung an WordPress geht weit über das Programmieren hinaus. Es ist ganz einfach, mehr darüber zu erfahren und sich zu engagieren. Entdecke die Teams, die auf <a href=\"https://make.wordpress.org/\">Make&nbsp;WordPress</a> aufgeführt sind, und nutze <a href=\"https://make.wordpress.org/contribute/\">dieses interaktive Tool</a>, um herauszufinden, welcher Bereich der richtige für dich ist.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"8505\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"WordPress 7.0.4 Sicherheitsrelease\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://de.wordpress.org/2026/08/wordpress-7-0-4-sicherheitsrelease/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 13 Aug 2026 16:24:06 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:10:\"Sicherheit\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://de.wordpress.org/?p=8493\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:456:\"WordPress 7.0.4 ist jetzt verfügbar WordPress 7.0.4 ist jetzt verfügbar und enthält einen Sicherheitspatch. Da es sich um eine Sicherheitsversion handelt, wird empfohlen, deine Websites umgehend zu aktualisieren. Du kannst auf WordPress 7.0.4 aktualisieren, indem du die Version von WordPress.org herunterlädst oder in deinem Dashboard unter Aktualisierungen“ auf „Version 7.0.4–de_DE installieren“ klickst. Websites, die automatische [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Torsten Landsiedel\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:3766:\"\n<h1 class=\"wp-block-heading\">WordPress 7.0.4 ist jetzt verfügbar</h1>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0.4 ist jetzt verfügbar und enthält einen Sicherheitspatch. Da es sich um eine Sicherheitsversion handelt, wird empfohlen, deine Websites umgehend zu aktualisieren.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Du kannst auf WordPress 7.0.4 aktualisieren, indem du die Version <a href=\"https://de.wordpress.org/wordpress-7.0.4-de_DE.zip\">von WordPress.org herunterlädst</a> oder in deinem Dashboard unter Aktualisierungen“ auf „<strong>Version 7.0.4–de_DE installieren</strong>“ klickst. Websites, die automatische Hintergrund-Updates unterstützen, werden in Kürze aktualisiert.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Weitere Informationen findest du auf der <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-0-4/\">WordPress 7.0.4 HelpHub-Seite</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">In dieser Version enthaltenes Sicherheitsupdate</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Das Sicherheitsteam bedankt sich beim Team von <a href=\"https://pwn.ai/\">pwn.ai</a> für die verantwortungsvolle Meldung der folgenden Sicherheitslücke und die Möglichkeit, diese in dieser Version zu beheben:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Remote-Code-Ausführung durch authentifizierte Autoren über das Hochladen bösartiger Dateien auf Websites, die Imagick und Ghostscript verwenden.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Aus Kulanz werden diese Korrekturen auf den 4.7-Zweig und die Version 7.1 RC3 zurückportiert, die im Laufe des heutigen Tages erscheinen soll. Zur Erinnerung: <strong>Nur die aktuellste Version von WordPress wird aktiv unterstützt.</strong> Die Backports sind in Arbeit und werden veröffentlicht, sobald sie fertig sind.</p>\n\n\n\n<h2 class=\"wp-block-heading\">CVE- und GHSA-Referenzen</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Weitere Details finden Sie in der Sicherheitsmitteilung: <a href=\"https://github.com/WordPress/wordpress-develop/security/advisories/GHSA-8vr3-7mxf-gx8w\">CVE-2026-65640 / GHSA-8vr3-7mxf-gx8w</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Vielen Dank an diese WordPress-Mitwirkenden</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Diese Veröffentlichung wurde von John Blackbourn geleitet, mit maßgeblichen Beiträgen von Dennis Snell und Jeremy Felt. Darüber hinaus wären WordPress 7.0.4 und die entsprechenden Backports ohne die wertvollen Beiträge der folgenden Personen nicht möglich gewesen:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/aaroncampbell\">Aaron D. Campbell</a>, <a href=\"https://profiles.wordpress.org/jorbin\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/adamsilverstein\">Adam Silverstein</a>, <a href=\"https://profiles.wordpress.org/wildworks\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/xknown\">Alex Concha</a>, <a href=\"https://profiles.wordpress.org/barry\">Barry</a>, <a href=\"https://profiles.wordpress.org/dmsnell\">Dennis Snell</a>, <a href=\"https://profiles.wordpress.org/ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://profiles.wordpress.org/jeremyfelt\">Jeremy Felt</a>, <a href=\"https://profiles.wordpress.org/johnbillion\">John Blackbourn</a>, <a href=\"https://profiles.wordpress.org/desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/lancewillett\">Lance Willett</a>, <a href=\"https://profiles.wordpress.org/tyxla\">Marin Atanasov</a>, <a href=\"https://profiles.wordpress.org/batmoo\">Mohammad Jangda</a>, <a href=\"https://profiles.wordpress.org/sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://profiles.wordpress.org/vortfu\">vortfu</a>, <a href=\"https://profiles.wordpress.org/westonruter\">Weston Ruter</a> sowie Vertreter von WP Engine.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"8493\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"WordPress 7.0.3 Sicherheitsrelease\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://de.wordpress.org/2026/08/wordpress-7-0-3-sicherheitsrelease/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 06 Aug 2026 20:06:01 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:10:\"Sicherheit\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://de.wordpress.org/?p=8489\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:470:\"WordPress 7.0.3 ist jetzt verfügbar WordPress 7.0.3 ist jetzt verfügbar und enthält mehrere Sicherheitskorrekturen. Da es sich um eine Sicherheitsversion handelt, wird empfohlen, deine Websites umgehend zu aktualisieren. Du kannst auf WordPress 7.0.3 aktualisieren, indem du die Version von de.wordpress.org herunterlädst oder in deinem Dashboard unter „Aktualisierungen“ auf „Version 7.0.3–de_DE installieren“ klicken. Websites, die automatische [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Torsten Landsiedel\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:8112:\"\n<h1 class=\"wp-block-heading\">WordPress 7.0.3 ist jetzt verfügbar</h1>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0.3 ist jetzt verfügbar und enthält mehrere Sicherheitskorrekturen. Da es sich um eine Sicherheitsversion handelt, wird empfohlen, deine Websites umgehend zu aktualisieren.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Du kannst auf WordPress 7.0.3 aktualisieren, indem du die Version <a href=\"https://de.wordpress.org/wordpress-7.0.3-de_DE.zip\">von de.wordpress.org herunterlädst</a> oder in deinem Dashboard unter „Aktualisierungen“ auf „Version 7.0.3–de_DE installieren“ klicken. Websites, die automatische Hintergrundaktualisierungen unterstützen, werden in Kürze aktualisiert.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Weitere Informationen findest du auf der <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-0-3/\">HelpHub-Seite zu WordPress 7.0.3</a> (EN).</p>\n\n\n\n<h2 class=\"wp-block-heading\">In dieser Version enthaltene Sicherheitsupdates</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Das Sicherheitsteam bedankt sich bei den folgenden Personen dafür, dass sie Sicherheitslücken verantwortungsbewusst gemeldet haben, sodass diese in dieser Version behoben werden konnten:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Ein vor der Authentifizierung auftretendes reflektiertes Cross-Site-Scripting (XSS) auf dem Anmeldebildschirm, das möglicherweise zur Ausführung von PHP-Code führen konnte, gemeldet vom Team bei pwn.ai.</li>\n\n\n\n<li>Von Asaf Mozes (<a href=\"https://hackerone.com/amosec?type=user\">amosec</a>) gemeldetes „Stored Cross-Site Scripting“ (XSS) in Beiträgen über das Emoji-Einstellungselement für „Contributor+“</li>\n\n\n\n<li>Von <a href=\"https://hackerone.com/n05ec\">n05ec</a> gemeldete „Contributor+“-Lücke: Speichergestütztes Cross-Site-Scripting (XSS) im Block „Beitragsinhalt“</li>\n\n\n\n<li>Von <a href=\"https://www.linkedin.com/in/naveens72/\">Naveen S</a> und <a href=\"https://www.linkedin.com/in/ajmalmoochingal/\">Ajmal Moochingal</a> gemeldete „Contributor+“-Lücke: Speichergestütztes Cross-Site-Scripting (XSS) in der Schnellbearbeitung auf Websites mit einer großen Anzahl von Benutzern</li>\n\n\n\n<li>Von <a href=\"https://profiles.wordpress.org/xknown/\">Alex Concha</a> vom WordPress-Sicherheitsteam gemeldete „Contributor+“-Lücke: Speichergestütztes Cross-Site-Scripting (XSS) im Block „Beitragsdatum“</li>\n\n\n\n<li>Ein Problem der Rechteausweitung in Multisite-Netzwerken mit aktivierter Benutzerregistrierung, das es einem Benutzer ermöglichte, eine neue Website zu erstellen – gemeldet von <a href=\"https://aikido.dev/\">Aikido Security</a></li>\n\n\n\n<li>Ein Problem mit der Offenlegung von Informationen im Block „Neueste Kommentare“, durch das Kommentare zu passwortgeschützten Beiträgen offengelegt wurden, gemeldet von <a href=\"https://profiles.wordpress.org/ehtis/\">Ehtisham Siddiqui</a> vom WordPress-Sicherheitsteam</li>\n\n\n\n<li>Aufzählung von Beitrags-Slugs, gemeldet von <a href=\"https://hdwsec.fr/\">HDWSec</a></li>\n\n\n\n<li>Offenlegung von Notizen in Kommentar-Feeds, gemeldet von <a href=\"https://profiles.wordpress.org/odkdn1/\">Elio Gubser</a></li>\n\n\n\n<li>CSS-Injektion über „Author+“ durch Umgehung des Filters für das „safe CSS“-Attribut, gemeldet von Anthropic</li>\n\n\n\n<li>Umgehung des Bestätigungsablaufs für E-Mail-Adressen, gemeldet von <a href=\"https://hackerone.com/0ways\">0ways</a></li>\n\n\n\n<li>Ein Server-Side Request Forgery (SSRF)-Problem bei der URL-Validierung, das Anfragen an link-lokale Bereiche zulässt, gemeldet von <a href=\"https://hackerone.com/andrewmohawk?type=user\">Andrew Mohawk</a> und mehreren unabhängigen Meldern</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Aus Kulanz werden diese Korrekturen, soweit erforderlich, auf alle Zweige zurückportiert, die für Sicherheitskorrekturen in Frage kommen (derzeit bis einschließlich 4.7). Zur Erinnerung: <strong>Nur die aktuellste Version von WordPress wird aktiv unterstützt.</strong> Die Backports sind in Arbeit und werden veröffentlicht, sobald sie fertig sind.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.1 RC2 wurde ebenfalls veröffentlicht und enthält alle relevanten Korrekturen.</p>\n\n\n\n<h2 class=\"wp-block-heading\">CVE- und GHSA-Referenzen</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Details zur XSS-Sicherheitslücke auf dem Anmeldebildschirm finden Sie in der Sicherheitsmitteilung: <a href=\"https://github.com/WordPress/wordpress-develop/security/advisories/GHSA-52p2-r8wf-jcrf\">CVE-2026-64638 / GHSA-52p2-r8wf-jcrf</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Vielen Dank an diese WordPress-Mitwirkenden</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Diese Veröffentlichung wurde von <a href=\"https://profiles.wordpress.org/johnbillion/\">John Blackbourn</a> geleitet. Neben den oben genannten Sicherheitsforschern wären WordPress 7.0.3 und die entsprechenden Backports ohne die bedeutenden Beiträge der folgenden Personen nicht möglich gewesen:</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://profiles.wordpress.org/aaroncampbell\">Aaron D. Campbell</a>, <a href=\"https://profiles.wordpress.org/jorbin\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/adamsilverstein\">Adam Silverstein</a>, <a href=\"https://profiles.wordpress.org/adrianmoldovanwp\">adrianmoldovanwp</a>, <a href=\"https://profiles.wordpress.org/wildworks\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/xknown\">Alex Concha</a>, <a href=\"https://profiles.wordpress.org/aduth\">Andrew Duthie</a>, <a href=\"https://profiles.wordpress.org/andrewserong\">Andrew Serong</a>, <a href=\"https://profiles.wordpress.org/annezazu\">annezazu</a>, <a href=\"https://profiles.wordpress.org/barry\">Barry</a>, <a href=\"https://profiles.wordpress.org/bernhard-reiter\">Bernie Reiter</a>, <a href=\"https://profiles.wordpress.org/villanovachile\">Daniel</a>, <a href=\"https://profiles.wordpress.org/talldanwp\">Daniel Richards</a>, <a href=\"https://profiles.wordpress.org/davidbinda\">David Biňovec</a>, <a href=\"https://profiles.wordpress.org/dmsnell\">Dennis Snell</a>, <a href=\"https://profiles.wordpress.org/ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://profiles.wordpress.org/erwanlr\">Erwan Le Rousseau</a>, <a href=\"https://profiles.wordpress.org/fabiankaegy/\">Fabian Kaegy</a>, <a href=\"https://profiles.wordpress.org/fiocavallari\">fiocavallari</a>, <a href=\"https://profiles.wordpress.org/mamaduka\">George Mamadashvili</a>, <a href=\"https://profiles.wordpress.org/odkdn1\">gubser</a>, <a href=\"https://profiles.wordpress.org/isabel_brison\">Isabel Brison</a>, <a href=\"https://profiles.wordpress.org/jsnajdr\">Jarda Snajdr</a>, <a href=\"https://profiles.wordpress.org/audrasjb\">Jb Audras</a>, <a href=\"https://profiles.wordpress.org/jeremyfelt\">Jeremy Felt</a>, <a href=\"https://profiles.wordpress.org/joedolson\">Joe Dolson</a>, <a href=\"https://profiles.wordpress.org/joehoyle\">Joe Hoyle</a>, <a href=\"https://profiles.wordpress.org/johnbillion\">John Blackbourn</a>, <a href=\"https://profiles.wordpress.org/jonsurrell\">Jon Surrell</a>, <a href=\"https://profiles.wordpress.org/desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/khokansardar\">Khokan Sardar</a>, <a href=\"https://profiles.wordpress.org/lancewillett\">Lance Willett</a>, <a href=\"https://profiles.wordpress.org/lucasbustamante\">lucasbustamante</a>, <a href=\"https://profiles.wordpress.org/lucatume\">lucatume</a>, <a href=\"https://profiles.wordpress.org/mciampini/\">Marco Ciampini</a>, <a href=\"https://profiles.wordpress.org/tyxla\">Marin Atanasov</a>, <a href=\"https://profiles.wordpress.org/batmoo\">Mohammad Jangda</a>, <a href=\"https://profiles.wordpress.org/mukesh27\">Mukesh Panchal</a>, <a href=\"https://profiles.wordpress.org/paulkevan\">Paul Kevan</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc\">Peter Wilson</a>, <a href=\"https://profiles.wordpress.org/ramonopoly\">ramonopoly</a>, <a href=\"https://profiles.wordpress.org/sergeybiryukov\">SergeyBiryukov</a>, <a href=\"https://profiles.wordpress.org/vortfu\">vortfu</a>, <a href=\"https://profiles.wordpress.org/westonruter\">Weston Ruter</a></p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"8489\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"WordPress 7.0.2 Sicherheitsrelease\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:68:\"https://de.wordpress.org/2026/07/wordpress-7-0-2-sicherheitsrelease/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 17 Jul 2026 20:35:38 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:10:\"Sicherheit\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://de.wordpress.org/?p=8466\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:454:\"WordPress 7.0.2 ist ab sofort verfügbar. Die Sicherheitsversion 7.0.2 behebt ein kritisches und ein hochgradiges Sicherheitsproblem. Da es sich um eine Sicherheitsversion handelt, wird empfohlen, deine Websites umgehend zu aktualisieren. Aufgrund der Schwere der Sicherheitslücken hat das WordPress.org-Team für Websites, auf denen betroffene Versionen laufen, erzwungene Updates über das automatische Update-System aktiviert. Um das Update [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Torsten Landsiedel\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:4366:\"\n<h2 class=\"wp-block-heading\">WordPress 7.0.2 ist ab sofort verfügbar.</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Die Sicherheitsversion 7.0.2 behebt ein kritisches und ein hochgradiges Sicherheitsproblem.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Da es sich um eine Sicherheitsversion handelt, <strong>wird empfohlen, deine Websites umgehend zu aktualisieren</strong>. Aufgrund der Schwere der Sicherheitslücken hat das WordPress.org-Team für Websites, auf denen betroffene Versionen laufen, erzwungene Updates über das automatische Update-System aktiviert.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Um das Update manuell durchzuführen, rufe dein WordPress-Dashboard auf, klicke auf „Aktualisierungen“ und anschließend auf „Version 7.0.2–de_DE installieren“, oder <a href=\"https://de.wordpress.org/wordpress-7.0.2-de_DE.zip\">lade WordPress 7.0.2 von WordPress.org herunter</a>. Auf Websites, die automatische Hintergrund-Updates unterstützen, wird der Update-Vorgang automatisch gestartet.</p>\n\n\n\n<h2 class=\"wp-block-heading\">In dieser Version enthaltene Sicherheitsupdates</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Das Sicherheitsteam bedankt sich bei den folgenden Personen für die verantwortungsvolle <a href=\"https://hackerone.com/wordpress\">Meldung</a> der Sicherheitslücken und die damit ermöglichte Behebung in dieser Version:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Ein Problem mit einer ermöglichten SQL-Injection, das gemeinsam von TF1T, dtro und haongo gemeldet wurde</li>\n\n\n\n<li>Ein Problem mit einer Verwechslung von REST-API-Batch-Routen und einer SQL-Injection, das zur Ausführung von Remote-Code führte und von Adam Kues bei <a href=\"https://slcyber.io\">Assetnote / Searchlight Cyber</a> gemeldet wurde</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Weitere Informationen zu dieser Version findest du auf der <a href=\"https://wordpress.org/documentation/wordpress-version/version-7-0-2/\">HelpHub-Website</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Backports</h2>\n\n\n\n<ul class=\"wp-block-list\">\n<li>WordPress 6.9 ist von beiden Sicherheitslücken betroffen. Es wurde die Version 6.9.5 veröffentlicht, die Korrekturen für beide Sicherheitslücken enthält.</li>\n\n\n\n<li>WordPress 6.8 ist nur von der ersten Sicherheitslücke betroffen. Es wurde die Version 6.8.6 veröffentlicht, die eine Korrektur enthält.</li>\n\n\n\n<li>Die Beta-Version von WordPress 7.1 ist von beiden Sicherheitslücken betroffen. Es wurde die Version 7.1 beta2 veröffentlicht, die Korrekturen für beide Sicherheitslücken enthält.</li>\n\n\n\n<li>Versionen von WordPress vor 6.8 sind nicht betroffen.</li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Vielen Dank an diese WordPress-Mitwirkenden</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Diese Version wurde von <a href=\"https://profiles.wordpress.org/johnbillion/\">John Blackbourn</a> und <a href=\"https://profiles.wordpress.org/barry/\">Barry Abrahamson</a> geleitet. Neben den oben genannten Sicherheitsforschern wäre WordPress 7.0.2 ohne die bedeutenden Beiträge der folgenden Personen nicht möglich gewesen: <a href=\"https://profiles.wordpress.org/jorbin\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/xknown\">Alex Concha</a>, <a href=\"https://profiles.wordpress.org/annezazu\">annezazu</a>, <a href=\"https://profiles.wordpress.org/Barry\">Barry</a>, <a href=\"https://profiles.wordpress.org/davidbaumwald\">David Baumwald</a>, <a href=\"https://profiles.wordpress.org/ocean90\">Dominik Schilling</a>, <a href=\"https://profiles.wordpress.org/ehtis\">Ehtisham Siddiqui</a>, <a href=\"https://profiles.wordpress.org/joedolson\">Joe Dolson</a>, <a href=\"https://profiles.wordpress.org/joehoyle\">Joe Hoyle</a>, <a href=\"https://profiles.wordpress.org/johnbillion\">John Blackbourn</a>, <a href=\"https://profiles.wordpress.org/desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/clorith\">Marius L. J.</a>, <a href=\"https://profiles.wordpress.org/Matt\">Matt Mullenweg</a>, <a href=\"https://profiles.wordpress.org/batmoo\">Mohammad Jangda</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc\">Peter Wilson</a>, <a href=\"https://profiles.wordpress.org/sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://profiles.wordpress.org/vortfu\">vortfu</a>, <a href=\"https://profiles.wordpress.org/westonruter\">Weston Ruter</a>, sowie Vertreter von Altis, Automattic, Bluehost, Cloudflare, GoDaddy, Hostinger und WP Engine.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"8466\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"WordPress 7.0.1 Wartungs-Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"https://de.wordpress.org/2026/07/wordpress-7-0-1-wartungs-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 13 Jul 2026 21:32:05 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://de.wordpress.org/?p=8455\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:423:\"WordPress 7.0.1 ist jetzt verfügbar! Diese kleinere Version enthält Fehlerbehebungen für 31 Fehler im Core und im Block-Editor und behebt Probleme, die mehrere Bereiche von WordPress betreffen, darunter den Block-Editor, die Admin-Oberfläche und die Medien. Eine vollständige Liste der Fehlerbehebungen findest du in der Ankündigung zum Release Candidate. WordPress 7.0.1 ist eine Wartungsversion mit kurzem [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Torsten Landsiedel\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:8843:\"\n<p class=\"wp-block-paragraph\"><strong>WordPress 7.0.1 ist jetzt verfügbar!</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Diese kleinere Version enthält Fehlerbehebungen für 31 Fehler im <a href=\"https://core.trac.wordpress.org/query?resolution=fixed&amp;milestone=7.0.1&amp;group=component&amp;col=id&amp;col=summary&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=status&amp;col=priority&amp;order=priority\">Core</a> und im <a href=\"https://core.trac.wordpress.org/changeset/62610\">Block-Editor</a> und behebt Probleme, die mehrere Bereiche von WordPress betreffen, darunter den Block-Editor, die Admin-Oberfläche und die Medien. Eine vollständige Liste der Fehlerbehebungen findest du in der <a href=\"https://make.wordpress.org/core/2026/07/01/wordpress-7-0-1-rc1-is-now-available/\">Ankündigung zum Release Candidate</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0.1 ist eine Wartungsversion mit kurzem Zyklus. Die nächste Hauptversion von WordPress wird 7.1 sein; die Veröffentlichung ist für den 19. August 2026 auf dem <a href=\"https://us.wordcamp.org/2026/\">WordCamp US</a> geplant.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Wenn du Websites hast, die automatische Hintergrund-Updates unterstützen, wird der Update-Vorgang automatisch gestartet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Du kannst <a href=\"https://de.wordpress.org/wordpress-7.0.1-de_DE.zip\">WordPress 7.0.1 von WordPress.org herunterladen</a> oder in deinem WordPress-Dashboard auf “Aktualisierungen“ und anschließend „Auf Version 7.0.1-de_DE aktualisieren“ klicken. Weitere Informationen zu dieser Version findest du auf der <a href=\"https://wordpress.org/support/wordpress-version/version-7-0-1\">HelpHub-Website</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Vielen Dank an diese WordPress-Mitwirkenden</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Diese Version wurde von <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/masteradhoc/\">Brian Haas</a>, <a href=\"https://profiles.wordpress.org/cbravobernal/\">Carlos Bravo</a> und <a href=\"https://profiles.wordpress.org/estelaris/\">Estela Rueda</a> geleitet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0.1 wäre ohne die Beiträge der folgenden Personen nicht möglich gewesen. Ihre asynchrone Zusammenarbeit bei der Einbindung von Wartungskorrekturen in eine stabile Version ist ein Beweis für die Stärke und Leistungsfähigkeit der WordPress-Community.</p>\n\n\n\n<p class=\"is-style-serif has-white-color has-text-color has-background has-link-color has-normal-font-size wp-elements-4 wp-block-paragraph\" style=\"background-color:#3e58e1\"><a href=\"https://profiles.wordpress.org/jorbin\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/abduremon\">Abdur Rahman Emon</a>, <a href=\"https://profiles.wordpress.org/abhishekfdd\">Abhishek Kumar</a>, <a href=\"https://profiles.wordpress.org/adamsilverstein\">Adam Silverstein</a>, <a href=\"https://profiles.wordpress.org/zieladam\">Adam Zieliński</a>, <a href=\"https://profiles.wordpress.org/iamadisingh\">Aditya Singh</a>, <a href=\"https://profiles.wordpress.org/wildworks\">Aki Hamano</a>, <a href=\"https://profiles.wordpress.org/afercia\">Andrea Fercia</a>, <a href=\"https://profiles.wordpress.org/andraganescu\">Andrei Draganescu</a>, <a href=\"https://profiles.wordpress.org/andrewserong\">Andrew Serong</a>, <a href=\"https://profiles.wordpress.org/annezazu\">annezazu</a>, <a href=\"https://profiles.wordpress.org/scruffian\">Ben Dwyer</a>, <a href=\"https://profiles.wordpress.org/bacoords\">Brian Coords</a>, <a href=\"https://profiles.wordpress.org/masteradhoc\">Brian Haas</a>, <a href=\"https://profiles.wordpress.org/cbravobernal\">Carlos Bravo</a>, <a href=\"https://profiles.wordpress.org/cogdesign\">cogdesign</a>, <a href=\"https://profiles.wordpress.org/danluu\">Dan Luu</a>, <a href=\"https://profiles.wordpress.org/talldanwp\">Daniel Richards</a>, <a href=\"https://profiles.wordpress.org/darshitrajyaguru97\">Darshit Rajyaguru</a>, <a href=\"https://profiles.wordpress.org/davidbaumwald\">David Baumwald</a>, <a href=\"https://profiles.wordpress.org/dmsnell\">Dennis Snell</a>, <a href=\"https://profiles.wordpress.org/dhruvang21\">Dhruvang21</a>, <a href=\"https://profiles.wordpress.org/ellatrix\">Ella Van Durpe</a>, <a href=\"https://profiles.wordpress.org/r1k0\">Erick Wambua</a>, <a href=\"https://profiles.wordpress.org/ecairol\">Esteban</a>, <a href=\"https://profiles.wordpress.org/estelaris\">Estela Rueda</a>, <a href=\"https://profiles.wordpress.org/mamaduka\">George Mamadashvili</a>, <a href=\"https://profiles.wordpress.org/gziolo\">Greg Ziółkowski</a>, <a href=\"https://profiles.wordpress.org/abcd95\">Himanshu Pathak</a>, <a href=\"https://profiles.wordpress.org/hbhalodia\">Hit Bhalodia</a>, <a href=\"https://profiles.wordpress.org/huzaifaalmesbah\">Huzaifa Al Mesbah</a>, <a href=\"https://profiles.wordpress.org/iflairwebtechnologies\">iflairwebtechnologies</a>, <a href=\"https://profiles.wordpress.org/jamesbregenzer\">James</a>, <a href=\"https://profiles.wordpress.org/jsnajdr\">Jarda Snajdr</a>, <a href=\"https://profiles.wordpress.org/audrasjb\">Jb Audras</a>, <a href=\"https://profiles.wordpress.org/joedolson\">Joe Dolson</a>, <a href=\"https://profiles.wordpress.org/joen\">Joen Asmussen</a>, <a href=\"https://profiles.wordpress.org/jonsurrell\">Jon Surrell</a>, <a href=\"https://profiles.wordpress.org/desrosj\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/karthikeya01\">Karthikeya Bethu</a>, <a href=\"https://profiles.wordpress.org/khokansardar\">Khokan Sardar</a>, <a href=\"https://profiles.wordpress.org/rlucian\">Lucian R.</a>, <a href=\"https://profiles.wordpress.org/luismulinari\">luismulinari</a>, <a href=\"https://profiles.wordpress.org/dervishov\">Mahammad Darvishov</a>, <a href=\"https://profiles.wordpress.org/manhar\">Manhar Barot</a>, <a href=\"https://profiles.wordpress.org/mciampini\">Marco Ciampini</a>, <a href=\"https://profiles.wordpress.org/tyxla\">Marin Atanasov</a>, <a href=\"https://profiles.wordpress.org/muryam\">Maryam Sultana</a>, <a href=\"https://profiles.wordpress.org/masum52\">Masum</a>, <a href=\"https://profiles.wordpress.org/mcsf\">Miguel Fonseca</a>, <a href=\"https://profiles.wordpress.org/369work\">Miroku</a>, <a href=\"https://profiles.wordpress.org/mohamedahamed\">Mohammed Noumaan Ahamed</a>, <a href=\"https://profiles.wordpress.org/mukesh27\">Mukesh Panchal</a>, <a href=\"https://profiles.wordpress.org/mustafabharmal\">Mustafa Bharmal</a>, <a href=\"https://profiles.wordpress.org/ntsekouras\">Nik Tsekouras</a>, <a href=\"https://profiles.wordpress.org/noruzzaman\">Noruzzaman</a>, <a href=\"https://profiles.wordpress.org/ozgursar\">Ozgur Sar</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc\">Peter Wilson</a>, <a href=\"https://profiles.wordpress.org/presskopp\">Presskopp</a>, <a href=\"https://profiles.wordpress.org/ekla\">Rahul Kumar</a>, <a href=\"https://profiles.wordpress.org/ramonopoly\">ramonopoly</a>, <a href=\"https://profiles.wordpress.org/youknowriad\">Riad Benguella</a>, <a href=\"https://profiles.wordpress.org/rishabhwp\">Rishabh Gupta</a>, <a href=\"https://profiles.wordpress.org/roshniahuja14\">Roshni Ahuja</a>, <a href=\"https://profiles.wordpress.org/sainathpoojary\">Sainath Poojary</a>, <a href=\"https://profiles.wordpress.org/sakshamsharma5\">Saksham Sharma</a>, <a href=\"https://profiles.wordpress.org/andrewssanya\">SAndrew</a>, <a href=\"https://profiles.wordpress.org/coffee2code\">Scott Reilly</a>, <a href=\"https://profiles.wordpress.org/sergeybiryukov\">Sergey Biryukov</a>, <a href=\"https://profiles.wordpress.org/siliconforks\">siliconforks</a>, <a href=\"https://profiles.wordpress.org/sabernhardt\">Stephen Bernhardt</a>, <a href=\"https://profiles.wordpress.org/swanandm\">Swanand M</a>, <a href=\"https://profiles.wordpress.org/inc2734\">Takashi Kitajima</a>, <a href=\"https://profiles.wordpress.org/edent\">Terence Eden</a>, <a href=\"https://profiles.wordpress.org/threadi\">threadi</a>, <a href=\"https://profiles.wordpress.org/tusharaddweb\">Tushar Patel</a>, <a href=\"https://profiles.wordpress.org/umesh.nevase\">Umesh Nevase</a>, <a href=\"https://profiles.wordpress.org/webmandesign\">WebMan Design | Oliver Juhas</a>, <a href=\"https://profiles.wordpress.org/westonruter\">Weston Ruter</a>, <a href=\"https://profiles.wordpress.org/yogeshbhutkar\">Yogesh Bhutkar</a>, <a href=\"https://profiles.wordpress.org/yusufmudagal\">Yusuf Mudagal</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">So kannst du mitwirken</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Um sich an der WordPress-Core-Entwicklung zu beteiligen, besuche Trac, <a href=\"https://core.trac.wordpress.org/report/6\">wähle ein Ticket</a> aus und beteilige dich an der Diskussion im Kanal <a href=\"https://wordpress.slack.com/archives/C02RQBWTW\">#core</a>. Benötigst du Hilfe? Wirf einen Blick in das <a href=\"https://make.wordpress.org/core/handbook/\">Handbuch für Core Contributor</a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"8455\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:29:\"WordPress 7.0 “Armstrong”\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:57:\"https://de.wordpress.org/2026/05/wordpress-7-0-armstrong/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 22 May 2026 09:52:01 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://de.wordpress.org/?p=8328\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:468:\"Jede WordPress-Version würdigt Künstlerinnen und Künstler, die die Musikwelt nachhaltig geprägt haben. Begrüße WordPress 7.0 „Armstrong“, benannt zu Ehren von „Satchmo“ höchstpersönlich – dem Jazzmusiker Louis Armstrong. Bekannt als der „erste große Jazz-Solist“ erschuf Louis Armstrong Ensembles, die seine außergewöhnlichen Fähigkeiten an der Trompete in den Mittelpunkt stellten, und verwandelte Jazz dabei von einer orchestralen [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Marcus Spanier\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:83735:\"\n<figure class=\"wp-block-image size-large\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/Release-Edition-Main-Image-7.0-1024x683.png\" alt=\"WP 7.0 Release Edition Main Image\" class=\"wp-image-20705\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Jede WordPress-Version würdigt Künstlerinnen und Künstler, die die Musikwelt nachhaltig geprägt haben. Begrüße WordPress 7.0 „Armstrong“, benannt zu Ehren von „Satchmo“ höchstpersönlich – dem Jazzmusiker Louis Armstrong.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Bekannt als der „erste große Jazz-Solist“ erschuf Louis Armstrong Ensembles, die seine außergewöhnlichen Fähigkeiten an der Trompete in den Mittelpunkt stellten, und verwandelte Jazz dabei von einer orchestralen in eine solistische Kunstform. Der Meistertrompeter begeisterte die Welt außerdem mit seiner unverwechselbaren Stimme, brachte Improvisation in den Jazz ein, beeinflusste zahllose Künstlerinnen und Künstler und veränderte die Musiklandschaft dauerhaft.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Louis Armstrong brachte seine persönliche Handschrift in die Welt des Jazz. Mit WordPress 7.0 „Armstrong“ kannst du deine eigene einbringen.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Willkommen bei WordPress 7.0!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 markiert den Beginn einer neuen Ära und legt die Grundlage für KI im gesamten WordPress-Erlebnis. Mit einem modernen, intuitiveren Dashboard führt 7.0 verbesserte Anpassungs- und Entwicklungswerkzeuge ein, die Kreativität fördern und endloses Potenzial freisetzen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Ob Creator, Unternehmerin oder Entwickler – mit WordPress 7.0 kannst du auf deine ganz eigene Weise gestalten.</p>\n\n\n\n<div class=\"wp-block-buttons is-layout-flex wp-block-buttons-is-layout-flex\">\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://de.wordpress.org/download/\">WordPress 7.0 herunterladen</a></div>\n</div>\n\n\n\n<h2 class=\"wp-block-heading\">Was steckt drin?</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Entdecke KI-Funktionen direkt in deiner Website – zentral verwaltet über einen einzigen Hub. Bewege dich mühelos durch das elegante neue Admin-Design im gesamten Dashboard. Neue Blöcke und Design-Werkzeuge fördern deinen kreativen Workflow, während eine umfangreiche Entwickler-Toolbox dir mehr Kontrolle denn je gibt.</p>\n\n\n\n<h3 class=\"wp-block-heading\">KI-integriertes WordPress</h3>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Die Möglichkeiten liegen in deinen Händen.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Mit KI, die in ganz WordPress integriert ist, sind die Möglichkeiten nahezu unbegrenzt. Ein neuer KI-Client im Core ermöglicht die Kommunikation mit generativen KI-Modellen, während Verbindungen bequem über einen zentralen Hub im Dashboard verwaltet werden. Zusammen mit der Abilities API schafft der KI-Client neue Funktionen, Workflow-Automatisierungen und kreative Werkzeuge für deine Website.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Installiere das neue KI-Plugin, um noch mehr Möglichkeiten freizuschalten: Bilder generieren und bearbeiten, Titel oder Auszüge erstellen oder sogar Alternativtexte vorschlagen lassen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 enthält außerdem ein neues Client-Side-Abilities-Paket: ein JavaScript-Gegenstück zur Abilities API mit integrierter Benutzeroberfläche und Befehlspalette, die umfangreiche neue und hybride KI-Funktionen bereitstellt.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-13-1024x632.png\" alt=\"\" class=\"wp-image-20700\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Verwalte alle externen Verbindungen zentral über den Connector-Bildschirm. Starte einfach mit drei Voreinstellungen oder füge eigene Verbindungen hinzu. Authentifizieren und KI-Funktionen aktivieren – gelingt mit nur wenigen Klicks.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-12-1024x632.png\" alt=\"\" class=\"wp-image-20699\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Ein KI-integriertes WordPress verspricht nahezu grenzenloses Potenzial – bereit, entdeckt zu werden.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Modernisiertes Dashboard</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Verbessere dein Admin-Erlebnis.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 bringt ein vollständig überarbeitetes Dashboard mit modernem Farbschema und klaren, eleganten Oberflächen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Sanfte Übergänge sorgen für ein flüssiges Erlebnis beim Wechsel zwischen verschiedenen Bereichen des Dashboards.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Mit nur einem Klick auf die neue Befehlspalette – erreichbar über <code>⌘K</code> oder <code>Ctrl+K</code> in der oberen Admin-Leiste – kannst du von überall im Dashboard auf deine wichtigsten Werkzeuge zugreifen.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-11-1024x632.png\" alt=\"\" class=\"wp-image-20698\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Verwalte Typografie zentral und unabhängig vom verwendeten Theme. Installiere, lade hoch und organisiere deine Schriftarten über die neue dedizierte Schriftarten-Bibliothek – mit Unterstützung für Block-, Hybrid- und klassische Themes.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-10-1024x632.png\" alt=\"\" class=\"wp-image-20697\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Durchsuche Revisionen visuell und erkenne Änderungen auf einen Blick. Marker machen redaktionelle Entscheidungen intuitiver, sodass du gewünschte Revisionen schnell auswählen und wiederherstellen kannst.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-9-1024x632.png\" alt=\"\" class=\"wp-image-20696\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Designen, erstellen, anpassen</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Ein einfacherer Weg zu gestalten.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Lass WordPress zu deiner kreativen Inspirationsquelle werden – mit neuen Blöcken, erweiterten Block-Optionen und Design-Werkzeugen, die mehr visuelle Flexibilität und präzisere Kontrolle bieten und dafür sorgen, dass jedes Element deiner Website konsistent bleibt.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Präsentiere deine Ideen mit dem neuen Galerie-Block als Lightbox-Diashow und optimiere deine Inhalte mit dem neuen Überschriften-Block. Sorge mit dem neuen Breadcrumbs-Block für klare Navigation und ergänze deine Designs mit dem neuen Icons-Block.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-8-1024x632.png\" alt=\"\" class=\"wp-image-20695\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Verbesserte Steuerelemente für Responsive Design in WordPress 7.0 machen deine Website benutzerfreundlicher. Blöcke lassen sich abhängig vom Gerät ein- oder ausblenden, ohne andere Ansichten zu beeinflussen.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-7-1024x632.png\" alt=\"\" class=\"wp-image-20694\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Gestalte und entwickle dein Menü-Overlay mit Blöcken und Patterns vollständig nach deinen Vorstellungen. Ergänze Spalten, passe Typografie an oder integriere eigene Schließen-Buttons direkt im Overlay. Starte mit einer Vorlage oder erstelle dein Menü komplett selbst.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-6-1024x632.png\" alt=\"\" class=\"wp-image-20693\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Verfeinere Seitenlayouts mit Mustern, die als eigenständige Einheiten funktionieren und sich bei Bedarf voneinander lösen lassen. Elemente können einfach ausgetauscht und individuell angepasst werden.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-5-1024x632.png\" alt=\"\" class=\"wp-image-20692\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Style jedes Detail deiner Inhalte mit benutzerdefiniertem CSS auf Block-Ebene – direkt im Beitrag oder auf der Seite.</p>\n\n\n\n<figure class=\"wp-block-image size-large has-custom-border\"><img decoding=\"async\" src=\"https://wordpress.org/news/files/2026/05/image-4-1024x632.png\" alt=\"\" class=\"wp-image-20691\" style=\"border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px\" /></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Werkzeugkasten für Entwicklerinnen und Entwickler</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Leistungsstarke Werkzeuge für deinen Workflow.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 ermöglicht schnelleres, besseres und flexibleres Entwickeln mit erweiterten APIs und verbesserter Funktionalität.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Erstelle Blöcke und Patterns auf Server-Ebene ausschließlich mit PHP – automatisch registriert über die Block-API.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Entdecke einen deutlich erweiterbaren Website-Editor mit Routing, Routenvalidierung und dem neuen <code>wordpress/boot</code>-Paket, mit dem Plugins eigene Seiten für den Website-Editor bereitstellen können.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Und vieles mehr</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Einen umfassenden Überblick über alle neuen Funktionen und Verbesserungen in WordPress 7.0 findest du auf der <a href=\"https://de.wordpress.org/download/releases/7.0/\" data-type=\"link\" data-id=\"https://wordpress.org/download/releases/7-0/\" target=\"_blank\" rel=\"noopener\">Feature-Showcase-Website (engl.)</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://de.wordpress.org/download/releases/7.0/\">Entdecke alle Neuerungen in 7.0</a></p>\n\n\n\n<h2 class=\"wp-block-heading\">Mehr über WordPress 7.0 erfahren</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://learn.wordpress.org/?utm_source=chatgpt.com\" target=\"_blank\" rel=\"noopener\">Learn WordPress</a> ist eine kostenlose Plattform für neue und erfahrene WordPress-Nutzerinnen und -Nutzer. Dort findest du Anleitungen zu zahlreichen WordPress-Funktionen, <a href=\"https://learn.wordpress.org/social-learning/\">interaktive Workshops</a> und strukturierte Lerninhalte für einen tieferen Einstieg.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Lies außerdem die <a target=\"_blank\" rel=\"noopener\" href=\"https://wordpress.org/documentation/wordpress-version/version-7-0/?utm_source=chatgpt.com\">WordPress-7.0-Release-Notes</a> mit Informationen zu Installation, Verbesserungen, behobenen Fehlern, Mitwirkenden und Lernressourcen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Im <a target=\"_blank\" rel=\"noopener\" href=\"https://make.wordpress.org/core/?utm_source=chatgpt.com\">WordPress-7.0-Field-Guide</a> findest du detaillierte Entwicklerhinweise zu den Änderungen dieser Version.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Das 7.0-Release-Team</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Jede Version wird von einem engagierten Team begeisterter Mitwirkender ermöglicht, die dafür sorgen, dass alles reibungslos und planmäßig voranschreitet. Das Team hinter WordPress 7.0 ist eine globale, funktionsübergreifende Gruppe von Mitwirkenden, die jederzeit bereit ist, Ideen voranzubringen, Hindernisse aus dem Weg zu räumen und Probleme zu lösen.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>Release Lead:&nbsp;<a href=\"https://profiles.wordpress.org/matveb/\">Matias Ventura</a></li>\n\n\n\n<li>Release Coordination:&nbsp;<a href=\"https://profiles.wordpress.org/chaion07/\">Ahmed Kabir Chaion</a>,&nbsp;<a href=\"https://profiles.wordpress.org/amykamala/\">Amy Kamala</a>,&nbsp;<a href=\"https://profiles.wordpress.org/4thhubbard/\">Mary Hubbard</a></li>\n\n\n\n<li>Tech Leads:&nbsp;<a href=\"https://profiles.wordpress.org/ellatrix/\">Ella van Durpe</a>,&nbsp;<a href=\"https://profiles.wordpress.org/mukesh27/\">Mukesh Panchal</a>,&nbsp;<a href=\"https://profiles.wordpress.org/sergeybiryukov/\">Sergey Biryukov</a></li>\n\n\n\n<li>Triage Leads:&nbsp;<a href=\"https://profiles.wordpress.org/audrasjb/\">Jb Audras</a>,&nbsp;<a href=\"https://profiles.wordpress.org/juanmaguitar/\">JuanMa Garrido</a></li>\n\n\n\n<li>Test Leads:&nbsp;<a href=\"https://profiles.wordpress.org/ankit-k-gupta/\">Ankit K Gupta</a>,&nbsp;<a href=\"https://profiles.wordpress.org/marybaum/\">Mary Baum</a></li>\n</ul>\n\n\n\n<h2 class=\"wp-block-heading\">Danke an alle Mitwirkenden</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Die Mission von WordPress ist es, das <a href=\"https://wordpress.org/about/\">Publizieren zu demokratisieren</a> und die <a href=\"https://opensource.org/osd-annotated\">Freiheiten von Open Source</a> zu fördern. Eine globale und vielfältige Community arbeitet täglich daran, die Software weiterzuentwickeln.</p>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 spiegelt die Leidenschaft und den Einsatz von mehr als 875 Mitwirkenden aus aller Welt wider. Außerdem begrüßt diese Version über 200 neue Beitragende, die zum ersten Mal an WordPress mitgewirkt haben.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Gemeinsam haben sie mehr als 420 Verbesserungen und Fehlerbehebungen umgesetzt – ein eindrucksvoller Beweis für die Stärke der Open-Source-Community von WordPress.</p>\n\n\n<p class=\"is-style-wporg-props-long alignfull\"><a href=\"https://profiles.wordpress.org/1000camels/\">1000camels</a> · <a href=\"https://profiles.wordpress.org/aakashverma1/\">Aakash Verma</a> · <a href=\"https://profiles.wordpress.org/aaroncampbell/\">Aaron D. Campbell</a> · <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a> · <a href=\"https://profiles.wordpress.org/aaronrobertshaw/\">Aaron Robertshaw</a> · <a href=\"https://profiles.wordpress.org/abdullah17/\">Abdullah Kaludi</a> · <a href=\"https://profiles.wordpress.org/abduremon/\">Abdur Rahman Emon</a> · <a href=\"https://profiles.wordpress.org/hiabhaykulkarni/\">Abhay Kulkarni</a> · <a href=\"https://profiles.wordpress.org/fitehal/\">Abhishek Deshpande</a> · <a href=\"https://profiles.wordpress.org/abhishekfdd/\">Abhishek Kumar</a> · <a href=\"https://profiles.wordpress.org/acmoifr/\">acmoifr</a> · <a href=\"https://profiles.wordpress.org/dannythedog/\">Adam</a> · <a href=\"https://profiles.wordpress.org/adamsilverstein/\">Adam Silverstein</a> · <a href=\"https://profiles.wordpress.org/zieladam/\">Adam Zieliński</a> · <a href=\"https://profiles.wordpress.org/adrianmoldovanwp/\">Adi Moldovan</a> · <a href=\"https://profiles.wordpress.org/oztaser/\">Adil Öztaşer</a> · <a href=\"https://profiles.wordpress.org/adithyanaik/\">adithyanaik</a> · <a href=\"https://profiles.wordpress.org/iamadisingh/\">Aditya Singh</a> · <a href=\"https://profiles.wordpress.org/adnanhyder/\">Adnan Hyder Pervez</a> · <a href=\"https://profiles.wordpress.org/adnanlimdi/\">adnan.limdi</a> · <a href=\"https://profiles.wordpress.org/adrianpiedra/\">adrianpiedra</a> · <a href=\"https://profiles.wordpress.org/adrmf25/\">adrmf25</a> · <a href=\"https://profiles.wordpress.org/afwebdev/\">afwebdev</a> ·