 <a href=\"https://profiles.wordpress.org/vishnuprajapat/\">vishnu prajapat</a> · <a href=\"https://profiles.wordpress.org/vortfu/\">vortfu</a> · <a href=\"https://profiles.wordpress.org/vrishabhsk/\">Vrishabh Jasani</a> · <a href=\"https://profiles.wordpress.org/waqassafdar/\">Waqas Safdar</a> · <a href=\"https://profiles.wordpress.org/wooxperto/\">WebCartisan</a> · <a href=\"https://profiles.wordpress.org/webmandesign/\">WebMan Design | Oliver Juhas</a> · <a href=\"https://profiles.wordpress.org/george9/\">webtasky</a> · <a href=\"https://profiles.wordpress.org/gauri87/\">WebTechee</a> · <a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a> · <a href=\"https://profiles.wordpress.org/wfmattr/\">WFMattR</a> · <a href=\"https://profiles.wordpress.org/skorasaurus/\">Will Skora</a> · <a href=\"https://profiles.wordpress.org/winsleyj/\">WinsleyJ</a> · <a href=\"https://profiles.wordpress.org/wiuempe/\">wiuempe</a> · <a href=\"https://profiles.wordpress.org/wolf45/\">wolf45</a> · <a href=\"https://profiles.wordpress.org/wongjn/\">wongjn</a> · <a href=\"https://profiles.wordpress.org/iqbal1hossain/\">WP Shark</a> · <a href=\"https://profiles.wordpress.org/wpexplorer/\">WPExplorer</a> · <a href=\"https://profiles.wordpress.org/wplmillet/\">wplmillet</a> · <a href=\"https://profiles.wordpress.org/wpsoul/\">wpsoul</a> · <a href=\"https://profiles.wordpress.org/wraithkenny/\">WraithKenny</a> · <a href=\"https://profiles.wordpress.org/x-raym/\">X-Raym</a> · <a href=\"https://profiles.wordpress.org/xate/\">xate</a> · <a href=\"https://profiles.wordpress.org/xavilc/\">xavilc</a> · <a href=\"https://profiles.wordpress.org/xwolf/\">xwolf</a> · <a href=\"https://profiles.wordpress.org/yagniksangani/\">Yagnik Sangani</a> · <a href=\"https://profiles.wordpress.org/yguyon/\">Yannis Guyon</a> · <a href=\"https://profiles.wordpress.org/getsyash/\">Yash B</a> · <a href=\"https://profiles.wordpress.org/yashjawale/\">Yash Jawale</a> · <a href=\"https://profiles.wordpress.org/yogeshbhutkar/\">Yogesh Bhutkar</a> · <a href=\"https://profiles.wordpress.org/fierevere/\">Yui</a> · <a href=\"https://profiles.wordpress.org/yusufmudagal/\">Yusuf Mudagal</a> · <a href=\"https://profiles.wordpress.org/zoe20/\">zoe20</a> · <a href=\"https://profiles.wordpress.org/zunaid321/\">Zunaid Amin</a> · <a href=\"https://profiles.wordpress.org/zuveria/\">zuveria</a> · <a href=\"https://profiles.wordpress.org/lstraczynski/\">Łukasz Strączyński</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Mehr als <a href=\"https://translate.wordpress.org/stats/\">70 Sprachversionen</a> haben WordPress 7.0 vollständig in ihre Sprache übersetzt. Die Community-Übersetzer arbeiten unermüdlich daran, dass weitere Übersetzungen folgen. Ein herzliches Dankeschön an alle, die dazu beitragen, WordPress in über 200 Sprachen verfügbar zu machen.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Vielen Dank auch an die <a href=\"https://make.wordpress.org/hosting/test-results/\">mehr als 21 Webhoster</a>, die Vorabversionen von WordPress 7.0 getestet haben. Sie haben maßgeblich dazu beigetragen, dass WordPress und die Hosting-Plattformen vollständig kompatibel, fehlerfrei und für das bestmögliche Nutzererlebnis optimiert sind.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Zu guter Letzt geht ein Dank an die Freiwilligen, die in den <a href=\"https://de.wordpress.org/support/\" target=\"_blank\" rel=\"noopener\">Support-Foren</a> mitwirken, indem sie Fragen von WordPress-Nutzerinnen und -Nutzern weltweit beantworten.</p>\n\n\n\n<h3 class=\"wp-block-heading\">Mach mit</h3>\n\n\n\n<p class=\"wp-block-paragraph\">Die Beteiligung an WordPress geht weit über das Programmieren hinaus. Es ist ganz einfach, mehr zu erfahren und einzusteigen. Entdecke die Teams, die zusammenkommen, um <a href=\"https://make.wordpress.org/\" target=\"_blank\" rel=\"noopener\">&#8222;Make WordPress&#8220; voranzubringen</a>, und nutze dieses <a href=\"https://make.wordpress.org/contribute/\" target=\"_blank\" rel=\"noopener\">interaktive Tool</a>, das dir bei der Entscheidung hilft, welches Team am besten zu dir passt.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"8328\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:60:\"\n		\n		\n		\n		\n		\n				\n		\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"WordPress 6.9.4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"https://de.wordpress.org/2026/03/wordpress-6-9-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 13 Mar 2026 07:29:13 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:2:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}i:1;a:5:{s:4:\"data\";s:10:\"Sicherheit\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://de.wordpress.org/?p=8287\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:479:\"WordPress 6.9.4 ist jetzt verfügbar! WordPress 6.9.2 und WordPress 6.9.3 wurden vorgestern veröffentlicht und beheben 10 Sicherheitsprobleme sowie einen Fehler, der das Laden von Vorlagendateien auf einer begrenzten Anzahl von Websites beeinträchtigte. Das WordPress-Sicherheitsteam hat festgestellt, dass nicht alle Sicherheitskorrekturen vollständig angewendet wurden. Daher wurde 6.9.4 mit den erforderlichen zusätzlichen Korrekturen veröffentlicht. Da es sich [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Torsten Landsiedel\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2518:\"\n<h2 class=\"wp-block-heading\">WordPress 6.9.4 ist jetzt verfügbar!</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://de.wordpress.org/2026/03/wordpress-6-9-2-sicherheitsrelease/\">WordPress 6.9.2</a> und <a href=\"https://de.wordpress.org/2026/03/wordpress-6-9-3/\">WordPress 6.9.3</a> wurden vorgestern veröffentlicht und beheben 10 Sicherheitsprobleme sowie einen Fehler, der das Laden von Vorlagendateien auf einer begrenzten Anzahl von Websites beeinträchtigte.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Das WordPress-Sicherheitsteam hat festgestellt, dass nicht alle Sicherheitskorrekturen vollständig angewendet wurden. Daher wurde 6.9.4 mit den erforderlichen zusätzlichen Korrekturen veröffentlicht.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Da es sich um eine Sicherheitsversion handelt, <strong>wird empfohlen, deine Websites umgehend zu aktualisieren.</strong></p>\n\n\n\n<p class=\"wp-block-paragraph\">Du kannst <a href=\"https://de.wordpress.org/wordpress-6.9.4-de_DE.zip\">WordPress 6.9.4 von WordPress.org herunterladen</a> oder dein WordPress-Dashboard aufrufen, auf „Aktualisierungen“ und dann auf „Jetzt aktualisieren“ klicken. Wenn du Websites hast, die automatische Hintergrund-Updates unterstützen, wird der Aktualisierungsvorgang automatisch gestartet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Weitere Informationen zu WordPress 6.9.4 findest du auf der <a href=\"https://wordpress.org/documentation/wordpress-version/version-6-9-4/\">Versionsseite der HelpHub-Website</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">In dieser Version enthaltene Sicherheitsupdates</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Das Sicherheitsteam bedankt sich bei den Mitwirkenden, die dieses Problem gemeldet und untersucht haben, insbesondere bei <a href=\"https://profiles.wordpress.org/kraftner\">Thomas Kräftner</a> für seine verantwortungsvolle Offenlegung. Die in 6.9.4 behobenen Sicherheitsprobleme sind:</p>\n\n\n\n<p class=\"wp-block-paragraph\">1. Ein PclZip-Path-Traversal-Problem, das unabhängig voneinander von <a href=\"https://profiles.wordpress.org/francescocarlucci/\">Francesco Carlucci</a> und <a href=\"https://profiles.wordpress.org/kaminuma/\">kaminuma</a> gemeldet wurde.</p>\n\n\n\n<p class=\"wp-block-paragraph\">2. Eine Umgehung der Autorisierung für die Notizfunktion, gemeldet von <a href=\"https://profiles.wordpress.org/kaminuma/\">kaminuma</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">3. Ein XXE in der externen getID3-Bibliothek, gemeldet von <a href=\"https://profiles.wordpress.org/regex33/\">Youssef Achtatal</a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"8287\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:57:\"\n		\n		\n		\n		\n		\n				\n		\n\n					\n										\n					\n		\n		\n			\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:4:{s:0:\"\";a:6:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"WordPress 6.9.3\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:49:\"https://de.wordpress.org/2026/03/wordpress-6-9-3/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 11 Mar 2026 08:25:39 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"category\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Releases\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:32:\"https://de.wordpress.org/?p=8282\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:11:\"isPermaLink\";s:5:\"false\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:432:\"WordPress 6.9.2 wurde gestern veröffentlicht und behob 10 Sicherheitsprobleme. Einige Benutzer haben anschließend ein Problem gemeldet, bei dem das Frontend ihrer Website nach dem Update auf 6.9.2 leer angezeigt wurde. Das Problem wurde auf einige Themes eingegrenzt, die einen ungewöhnlichen Ansatz zum Laden von Vorlagendateien über „stringable objects“ anstelle von primitiven Strings für Dateipfade verwenden. [&#8230;]\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Torsten Landsiedel\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:40:\"http://purl.org/rss/1.0/modules/content/\";a:1:{s:7:\"encoded\";a:1:{i:0;a:5:{s:4:\"data\";s:2106:\"\n<p class=\"wp-block-paragraph\"><a href=\"https://de.wordpress.org/2026/03/wordpress-6-9-2-sicherheitsrelease/\">WordPress 6.9.2 wurde gestern veröffentlicht</a> und behob 10 Sicherheitsprobleme.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Einige Benutzer haben anschließend ein Problem gemeldet, bei dem das Frontend ihrer Website nach dem Update auf 6.9.2 leer angezeigt wurde. Das Problem wurde auf einige Themes eingegrenzt, die einen ungewöhnlichen Ansatz zum Laden von Vorlagendateien über „stringable objects“ anstelle von primitiven Strings für Dateipfade verwenden.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Obwohl dies kein offiziell unterstützter Ansatz zum Laden von Vorlagendateien in WordPress ist (der Filter „template_include” akzeptiert nur Zeichenfolgen), führte dies dennoch dazu, dass einige Websites nicht mehr funktionierten. Daher hat das Sicherheitsteam beschlossen, dieses Problem in einer schnellen Folgeversion 6.9.3 zu beheben.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Wie immer <strong>wird empfohlen, deine Websites sofort auf die neueste Version von WordPress zu aktualisieren</strong>. Dadurch wird sichergestellt, dass deine Website durch alle in 6.9.2 verfügbaren Sicherheitskorrekturen geschützt ist und du nicht von dem in 6.9.3 behobenen Fehler betroffen bist.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Vielen Dank an alle, die das Problem gemeldet, bei der Eingrenzung des Problems geholfen und bei der Behebung mitgewirkt haben.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Du kannst <a href=\"https://de.wordpress.org/wordpress-6.9.3-de_DE.zip\">WordPress 6.9.3 von WordPress.org herunterladen</a> oder Ihr WordPress-Dashboard aufrufen, auf Aktualisierungen“ und dann auf „Jetzt aktualisieren“ klicken. Wenn du Websites hast, die automatische Hintergrund-Updates unterstützen, wird der Aktualisierungsvorgang in Kürze beginnen. Du musst nichts weiter tun!</p>\n\n\n\n<p class=\"wp-block-paragraph\">Weitere Informationen zu WordPress 6.9.3 findest du auf der <a href=\"https://wordpress.org/documentation/wordpress-version/version-6-9-3/\">Versionsseite der HelpHub-Website</a>.</p>\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:7:\"post-id\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"8282\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}s:27:\"http://www.w3.org/2005/Atom\";a:1:{s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:0:\"\";s:7:\"attribs\";a:1:{s:0:\"\";a:3:{s:4:\"href\";s:48:\"https://de.wordpress.org/category/releases/feed/\";s:3:\"rel\";s:4:\"self\";s:4:\"type\";s:19:\"application/rss+xml\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:44:\"http://purl.org/rss/1.0/modules/syndication/\";a:2:{s:12:\"updatePeriod\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"\n	hourly	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:15:\"updateFrequency\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"\n	1	\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:30:\"com-wordpress:feed-additions:1\";a:1:{s:4:\"site\";a:1:{i:0;a:5:{s:4:\"data\";s:9:\"255165085\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}}}}}}}}s:4:\"type\";i:128;s:7:\"headers\";a:12:{s:6:\"server\";s:5:\"nginx\";s:4:\"date\";s:29:\"Wed, 23 Sep 2026 20:11:26 GMT\";s:12:\"content-type\";s:34:\"application/rss+xml; charset=UTF-8\";s:4:\"vary\";s:37:\"Accept-Encoding, accept, content-type\";s:6:\"x-olaf\";s:3:\"⛄\";s:13:\"last-modified\";s:29:\"Tue, 22 Sep 2026 16:12:21 GMT\";s:12:\"x-robots-tag\";s:15:\"noindex, follow\";s:4:\"link\";s:62:\"<https://de.wordpress.org/category/releases/>; rel=\"canonical\"\";s:15:\"x-frame-options\";s:10:\"SAMEORIGIN\";s:16:\"content-encoding\";s:4:\"gzip\";s:7:\"alt-svc\";s:5:\"clear\";s:4:\"x-nc\";s:9:\"HIT dca 2\";}s:5:\"build\";i:1760643936;s:21:\"cache_expiration_time\";i:1790237486;s:23:\"__cache_expiration_time\";i:1790237486;}', 'off');
